const taskEndpointBase=taskEndpoint;taskEndpoint=async function(req,action,id){const path=new URL(req.url).pathname,suffix=path.split("/").pop();if(action==="unknown"&&(suffix==="approve"||suffix==="cancel"))action=suffix;const now=Date.now();if(action==="create"){const response=await taskEndpointBase(req,action,id),body=await response.json();if(body.task){const t=TASKS.get(body.task.id);if(t){t.expires_at=now+15*60_000;t.approval_status=t.approval_required?"pending":"not_required";body.task=t}}return json(body,response.status)}if(action==="approve"||action==="cancel"){const b=await readJson(req),t=TASKS.get(id);if(!t)throw new ClientError("Tâche introuvable.","TASK_NOT_FOUND",404);if(t.expires_at&&now>t.expires_at){t.state="expired";throw new ClientError("La proposition a expiré.","TASK_EXPIRED",409)}if(action==="approve"&&b.explicit_approval!==true)throw new ClientError("Une validation explicite est requise.","HUMAN_APPROVAL_REQUIRED",403);if(action==="approve"){if(t.state!=="simulated")throw new ClientError("Seule une simulation peut être validée.","TASK_STATE_INVALID",409);t.approval_status="approved";t.state="validated";t.executed=false;audit("task_approved",req,{task_id:id});return json({ok:true,validated:true,executed:false,task:t})}if(t.state==="executed")throw new ClientError("Tâche déjà exécutée.","TASK_ALREADY_EXECUTED",409);t.state="cancelled";t.approval_status="cancelled";audit("task_cancelled",req,{task_id:id});return json({ok:true,cancelled:true,executed:false,task:t})}if(TASKS.has(id)){const t=TASKS.get(id);if(t.expires_at&&now>t.expires_at){t.state="expired";return json({ok:false,error:"La tâche a expiré.",code:"TASK_EXPIRED"},409)}}return taskEndpointBase(req,action,id)}

