function secret(v){return/(?:password|mot de passe|api[_ -]?key|secret|token|bearer|private[_ -]?key)\s*[:=]\s*\S+/i.test(String(v||""))||/\b(?:sk-[\w-]{16,}|gh[pousr]_[A-Za-z0-9]{20,}|AKIA[A-Z0-9]{16})\b/.test(String(v||""))}
