async function professorStats(env){const [s,t,q,r,l,p,f]=await Promise.all([env.DB.prepare("SELECT COUNT(*) n FROM professor_sessions").first(),env.DB.prepare("SELECT COUNT(*) n FROM professor_turns").first(),env.DB.prepare("SELECT COUNT(*) n FROM professor_turns WHERE kind='question'").first(),env.DB.prepare("SELECT COUNT(*) n FROM professor_turns WHERE kind='retest'").first(),env.DB.prepare("SELECT COUNT(*) n FROM professor_lessons WHERE understanding_status='understood'").first(),env.DB.prepare("SELECT COUNT(*) n FROM professor_lessons WHERE understanding_status IN ('pending_retest','retry_required')").first(),env.DB.prepare("SELECT COUNT(*) n FROM professor_turns WHERE kind='retest' AND passed=0").first()]);return json({version:APP_VERSION,sessions:Number(s&&s.n)||0,turns:Number(t&&t.n)||0,questions:Number(q&&q.n)||0,retests:Number(r&&r.n)||0,validated_lessons:Number(l&&l.n)||0,understood_lessons:Number(l&&l.n)||0,pending_retests:Number(p&&p.n)||0,failed_retests:Number(f&&f.n)||0,criterion:"understood only after passed retest"})}
const PROFESSOR_PAGE='<html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MELITURGOS — Professeur</title><style>body{margin:0;background:#0c0c0e;color:#eee;font:16px system-ui}main{max-width:900px;margin:auto;padding:24px 16px}section{background:#151518;border:1px solid #29292f;border-radius:16px;padding:16px;margin:12px 0}.grid{display:grid;gap:8px}textarea,input{width:100%;box-sizing:border-box;background:#101014;color:#fff;border:1px solid #3a3a42;border-radius:10px;padding:11px;margin:6px 0}button{background:#292932;color:#fff;border:1px solid #4a4a55;border-radius:10px;padding:10px;margin:4px;cursor:pointer}.answer,.meta{white-space:pre-wrap;background:#222227;padding:12px;border-radius:10px}.meta{background:transparent;color:#aaa;font-size:13px}</style></head><body><main><p><a href="/" style="color:#aaa">← MELITURGOS</a></p><h1>Mode Professeur / ChatGPT Work</h1><p class="meta">Session guidée sans accès aux secrets, Cloudflare ou déploiement.</p><section><button id="start-session">Démarrer une session</button><input id="session-goal" placeholder="Objectif"><div id="session-id" class="meta"></div></section><section class="grid" id="professor-media"><strong>Médias privés (R2)</strong><input id="professor-media-file" type="file" accept="image/jpeg,image/png,image/webp,audio/webm,audio/wav,audio/mpeg,video/webm,video/mp4"><button id="professor-media-upload" type="button">Envoyer le média</button><div id="professor-media-status" class="meta">Analyse indisponible ; sélectionnez un média après une question.</div></section><section class="grid"><textarea id="professor-question" placeholder="Question"></textarea><button id="send-question">Poser la question</button><div id="meliturgos-answer" class="answer"></div><div id="professor-evidence" class="meta"></div></section><section class="grid"><textarea id="professor-critique" placeholder="Critique"></textarea><textarea id="professor-correction" placeholder="Correction"></textarea><textarea id="improved-answer" placeholder="Meilleure réponse"></textarea><button id="send-correction">Envoyer la correction</button><button id="save-lesson">Valider comme leçon</button><textarea id="retest-question" placeholder="Question de retest"></textarea><label><input type="checkbox" id="retest-passed"> Compréhension validée</label><button id="retest">Nouvelle réponse / retest</button><button id="finish-session">Terminer la session</button><div id="professor-status" class="meta"></div></section><script>const q=s=>document.querySelector(s);let sid=null,tid=null;async function api(p,o){o=o||{};o.headers=Object.assign({"content-type":"application/json"},o.headers||{});const r=await fetch(p,o),t=await r.text();let j;try{j=JSON.parse(t)}catch{throw Error("Réponse non JSON")}if(!r.ok)throw Error(j.error||("HTTP "+r.status));return j}function fail(e){q("#professor-status").textContent="Erreur : "+e.message}q("#start-session").onclick=async()=>{try{const j=await api("/api/professor/session",{method:"POST",body:JSON.stringify({goal:q("#session-goal").value})});sid=j.session_id;q("#session-id").textContent="Session "+sid;window.dispatchEvent(new Event("professor-state"))}catch(e){fail(e)}};q("#send-question").onclick=async()=>{try{if(!sid)throw Error("Démarre une session");const j=await api("/api/professor/ask",{method:"POST",body:JSON.stringify({session_id:sid,question:q("#professor-question").value})});tid=j.turn_id;window.dispatchEvent(new Event("professor-state"));q("#meliturgos-answer").textContent=j.answer;q("#professor-evidence").textContent="Souvenirs : "+j.memories.length+"\\nConfiance : "+j.confidence+"\\nProvenance : "+(j.provenance||"professor_question")+"\\nSpécialiste : "+(j.specialist||"general_model")+"\\nOutils : "+Object.keys(j.tools).join(", ")}catch(e){fail(e)}};q("#send-correction").onclick=async()=>{try{await api("/api/professor/correct",{method:"POST",body:JSON.stringify({session_id:sid,turn_id:tid,critique:q("#professor-critique").value,correction:q("#professor-correction").value,improved_answer:q("#improved-answer").value})});q("#professor-status").textContent="Correction enregistrée"}catch(e){fail(e)}};q("#save-lesson").onclick=async()=>{try{const lesson=q("#professor-correction").value||q("#improved-answer").value;if(!sid||!tid||!lesson)throw Error("Correction et tour requis");const j=await api("/api/professor/lesson",{method:"POST",body:JSON.stringify({session_id:sid,turn_id:tid,lesson,rationale:q("#professor-critique").value})});q("#professor-status").textContent="Leçon validée, memory_id="+j.memory_id}catch(e){fail(e)}};q("#retest").onclick=async()=>{try{const j=await api("/api/professor/retest",{method:"POST",body:JSON.stringify({session_id:sid,question:q("#retest-question").value,passed:q("#retest-passed").checked})});tid=j.turn_id;q("#meliturgos-answer").textContent=j.answer;q("#professor-evidence").textContent="Retest · souvenirs : "+j.memories.length+" · leçons : "+j.lessons.length}catch(e){fail(e)}};q("#finish-session").onclick=async()=>{try{if(!sid)throw Error("Aucune session");q("#professor-status").textContent="Session persistée : "+sid;await api("/api/professor/session/"+sid)}catch(e){fail(e)}};q("#professor-media-upload").onclick=()=>{q("#professor-media-status").textContent="Téléversement désactivé : validation R2 requise.";};</script></main></body></html>';
async function professorPage(){const base=html(PROFESSOR_PAGE),body=await base.text(),panel='<section class="grid" id="capability-panel"><h2>Outils et modèles</h2><p class="meta">État réel des capacités. Une capacité indisponible n’est jamais présentée comme exécutée.</p><button id="refresh-capabilities" type="button">Actualiser les capacités</button><div id="capability-list" class="meta">Chargement…</div></section><script>(function(){var list=document.querySelector("#capability-list"),button=document.querySelector("#refresh-capabilities");async function refresh(){list.textContent="Chargement…";try{var registry=await api("/api/tools/registry"),lines=registry.tools.map(function(t){return (t.available?"✓":"○")+" "+t.name+" — "+t.effective_status+" — "+t.capability+"\\n  "+t.explanation});list.textContent=lines.join("\\n\\n")}catch(e){list.textContent="Registre indisponible : "+e.message}}button.onclick=refresh;refresh()})();</script>';return new Response(body.replace("</main>",panel+"</main>"),{status:base.status,headers:base.headers})}
const professorPageWithKnowledge=professorPage;professorPage=async function(){const base=await professorPageWithKnowledge(),body=await base.text(),panel='<section class="grid" id="knowledge-panel"><h2>Knowledge contrôlé</h2><p class="meta">Sources et imports restent privés, textuels et révocables. Aucune source n’est active sans autorisation explicite.</p><input id="knowledge-source-id" placeholder="ID source"><button id="knowledge-load" type="button">Charger source/import</button><button id="knowledge-revoke" type="button">Révoquer la source</button><div id="knowledge-state" class="meta">Aucune source chargée</div><script>(function(){var id=document.querySelector("#knowledge-source-id"),state=document.querySelector("#knowledge-state");document.querySelector("#knowledge-load").onclick=async function(){try{if(!id.value.trim())throw Error("ID source requis");var s=await api("/api/knowledge/source/"+encodeURIComponent(id.value.trim())),i=await api("/api/knowledge/import/"+encodeURIComponent(id.value.trim()));state.textContent="Source : "+s.source.name+" · statut "+s.source.status+" · confiance "+s.source.confidence+"\\nImports : "+(i.import?i.import.status:"introuvable")+" · erreurs : "+(i.import?i.import.error||"aucune":"-")}catch(e){state.textContent="Knowledge indisponible : "+e.message}};document.querySelector("#knowledge-revoke").onclick=async function(){try{if(!id.value.trim())throw Error("ID source requis");var r=await api("/api/knowledge/source/"+encodeURIComponent(id.value.trim())+"/revoke",{method:"POST",body:JSON.stringify({})});state.textContent="Source révoquée logiquement : "+r.status}catch(e){state.textContent="Révocation refusée : "+e.message}}})();</script></section>';return new Response(body.replace("</main>",panel+"</main>"),{status:base.status,headers:base.headers})}
const professorPageWithWorkflows=professorPage;professorPage=async function(){const base=await professorPageWithWorkflows(),body=await base.text(),panel='<section class="grid" id="workflow-improvements"><h2>Mesure et améliorations proposées</h2><p class="meta">Les variantes sont simulées uniquement et ne remplacent jamais le workflow stable.</p><button id="workflow-refresh" type="button">Mesurer les workflows</button><div id="workflow-results" class="meta">Aucune mesure chargée</div><script>(function(){var out=document.querySelector("#workflow-results");document.querySelector("#workflow-refresh").onclick=async function(){try{var s=await api("/api/tools/workflows/status"),v=await api("/api/tools/workflows/variant?workflow=professor&variant=detail-v1&simulation=true");out.textContent=JSON.stringify({mesures:s.workflows,proposition:v.proposal},null,2)}catch(e){out.textContent="Mesure indisponible : "+e.message}}})();</script></section>';return new Response(body.replace("</main>",panel+"</main>"),{status:base.status,headers:base.headers})}
const professorPageWithSpecialists=professorPage;professorPage=async function(){const base=await professorPageWithSpecialists(),body=await base.text(),panel='<section class="grid" id="specialist-router"><h2>Spécialistes et routeur</h2><p class="meta">Profils séparés du modèle général ; tous désactivés jusqu’à validation.</p><button id="specialist-refresh" type="button">Afficher les spécialistes</button><div id="specialist-results" class="meta">Aucun spécialiste sélectionné</div><script>(function(){var out=document.querySelector("#specialist-results");document.querySelector("#specialist-refresh").onclick=async function(){try{var s=await api("/api/tools/specialists/status"),r=await api("/api/tools/specialists/select?q="+encodeURIComponent("Explique ce souvenir"));out.textContent=JSON.stringify({specialists:s.specialists,selection:r},null,2)}catch(e){out.textContent="Routeur indisponible : "+e.message}}})();</script></section>';return new Response(body.replace("</main>",panel+"</main>"),{status:base.status,headers:base.headers})}
