const WORKFLOW_VARIANTS=new Map();const WORKFLOW_NAMES=["professor","knowledge","voice","connectors","memory","media"];
function workflowErrorClass(code){const c=String(code||"").toUpperCase();if(/MISSING|REQUIRED|EMPTY|NOT_FOUND/.test(c))return"missing_data";if(/UNAVAILABLE|DISABLED|NOT_CONFIGURED|BINDING/.test(c))return"tool_unavailable";if(/UNCERTAIN|LOW_CONFIDENCE|REJECTED/.test(c))return"uncertain_response";if(/INPUT|QUESTION|CORRECTION/.test(c))return"misunderstanding";return"technical"}
async function workflowMetrics(env){const start=Date.now(),metrics=[];for(const name of WORKFLOW_NAMES){let success=0,errors=0,feedback=0,retest=0;try{if(name==="memory"){success=Number((await env.DB.prepare("SELECT COUNT(*) n FROM memories").first())?.n)||0;feedback=Number((await env.DB.prepare("SELECT COUNT(*) n FROM interactions WHERE feedback IS NOT NULL").first())?.n)||0}if(name==="professor"){success=Number((await env.DB.prepare("SELECT COUNT(*) n FROM professor_turns").first())?.n)||0;retest=Number((await env.DB.prepare("SELECT COUNT(*) n FROM professor_turns WHERE kind='retest' AND passed=1").first())?.n)||0}if(name==="knowledge")success=Number((await env.DB.prepare("SELECT COUNT(*) n FROM knowledge_passages WHERE active=1").first())?.n)||0;if(name==="voice")success=0;if(name==="connectors")success=0;if(name==="media")success=Number((await env.DB.prepare("SELECT COUNT(*) n FROM media_assets WHERE access_status='private'").first())?.n)||0}catch(e){errors++;}metrics.push({workflow:name,success_count:success,error_count:errors,duration_ms:Date.now()-start,feedback_count:feedback,retest_quality:retest,cost_estimated_usd:name==="voice"?0.005:name==="professor"?0.005:0,error_classes:errors?[workflowErrorClass("TECHNICAL_ERROR")]:[],stable:true})}return metrics}
const toolsBase=tools;tools=async function(req,env,name){const u=new URL(req.url);if(name==="workflows/status"){const metrics=await workflowMetrics(env);return json({version:APP_VERSION,mode:"observability_only",workflows:metrics,limits:{retention:"non-persistent summary",max_rows:100},variants:Array.from(WORKFLOW_VARIANTS.values()).map(v=>({...v,active:false}))})}if(name==="workflows/variant"){const workflow=u.searchParams.get("workflow")||"",variant=u.searchParams.get("variant")||"candidate",simulation=u.searchParams.get("simulation")==="true";if(!WORKFLOW_NAMES.includes(workflow))throw new ClientError("Workflow inconnu.","WORKFLOW_NOT_FOUND",404);if(!simulation)throw new ClientError("Le mode simulation est obligatoire.","SIMULATION_REQUIRED",409);const id=workflow+":"+variant,proposal={id,workflow,variant,mode:"simulation",executed:false,active:false,stable_comparison:{criteria:["success_count","error_count","duration_ms","feedback_count","retest_quality","cost_estimated_usd"],decision:"stable_conserved_until_human_validation"},error_classification:["missing_data","tool_unavailable","misunderstanding","uncertain_response","technical"],rollback:"workflow stable inchangé"};WORKFLOW_VARIANTS.set(id,proposal);return json({ok:true,proposal})}return toolsBase(req,env,name)}
const SPECIALISTS=[{id:"professor",label:"Professor / pédagogie",tasks:["conversation","reasoning","summary"],permissions:["professor.read","professor.write","memory.read","ai.inference"],sources:["professor_sessions","memories"],risk:"low",status:"disabled"},{id:"memory",label:"Spécialiste mémoire",tasks:["memory"],permissions:["memory.read","memory.count"],sources:["D1.memories","D1.interactions"],risk:"read",status:"disabled"},{id:"knowledge",label:"Knowledge / recherche",tasks:["research"],permissions:["knowledge.read","sources.read"],sources:["knowledge_sources","knowledge_passages"],risk:"read",status:"disabled"},{id:"voice",label:"Voix",tasks:["multimedia"],permissions:["audio.transcription","ai.inference"],sources:["request audio (non persistant)"],risk:"read",status:"disabled"},{id:"multimedia",label:"Multimédia",tasks:["multimedia"],permissions:["media.read"],sources:["MEDIA_BUCKET privé"],risk:"read",status:"disabled"},{id:"security",label:"Sécurité",tasks:["security"],permissions:["governance.read","diagnostic.read"],sources:["configuration"],risk:"read",status:"disabled"},{id:"connectors",label:"Connecteurs",tasks:["connectors"],permissions:["connector.readonly"],sources:["déclarations de connecteurs"],risk:"read",status:"disabled"}];
function specialistForTask(task,text=""){const id=task==="research"?"knowledge":task==="memory"?"memory":task==="multimedia"?( /image|photo|vidéo|video/i.test(text)?"multimedia":"voice"):"professor";return SPECIALISTS.find(s=>s.id===id)||SPECIALISTS[0]}
const toolsSpecialistsBase=tools;tools=async function(req,env,name){const u=new URL(req.url);if(name==="specialists/status")return json({version:APP_VERSION,default:"general_model",specialists:SPECIALISTS.map(s=>({...s,available:false,effective_status:"disabled",fallback:"general_model"}))});if(name==="specialists/select"){const text=u.searchParams.get("q")||"",task=classifyTask(text),s=specialistForTask(task,text),requestedTool=u.searchParams.get("tool")||null;return json({task,selected:s.available? s.id:"general_model",specialist:s.id,reason:`Tâche ${task} → ${s.label}; spécialiste désactivé par défaut`,fallback:"general_model",permissions:s.permissions,tool_allowed:requestedTool? s.permissions.includes(requestedTool):null,simulation:true,active:false})}return toolsSpecialistsBase(req,env,name)}
async function knowledgeImportGet(env,id){const r=await env.DB.prepare("SELECT id,source_id,status,idempotency_key,created_at,updated_at,passage_count,error FROM knowledge_imports WHERE id=?").bind(id).first();if(!r)throw new ClientError("Import introuvable.","IMPORT_NOT_FOUND",404);return json({import:r})}
async function knowledgeForPrompt(env,q){const n=normalize(q);if(!n)return[];const like="%"+n.split(" ").filter(Boolean).slice(0,5).join("%")+"%";const r=await env.DB.prepare("SELECT p.id,p.source_id,p.title,p.text,p.source_date,p.confidence,s.name,s.author,s.url FROM knowledge_passages p JOIN knowledge_sources s ON s.id=p.source_id WHERE p.active=1 AND s.status='active' AND lower(p.text) LIKE ? ORDER BY p.confidence DESC,p.source_date DESC LIMIT 6").bind(like).all();return(r.results||[]).map(x=>({passage_id:x.id,source_id:x.source_id,title:x.title,text:x.text,confidence:Number(x.confidence)||0,source:x.name,author:x.author,url:x.url,date:x.source_date,citation:"knowledge_sources/"+x.source_id+"#passage-"+x.id}))}
